import{_ as t}from"./chunks/knowledge-base.Co7nYv_M.js";import{_ as a,o,c as n,ai as r}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Knowledge Base","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/knowledge-base.md","filePath":"en/guide/knowledge-base.md"}'),s={name:"en/guide/knowledge-base.md"};function i(l,e,d,c,h,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="knowledge-base" tabindex="-1">Knowledge Base <a class="header-anchor" href="#knowledge-base" aria-label="Permalink to &quot;Knowledge Base&quot;">​</a></h1><p>The Knowledge Base page implements a complete local RAG (Retrieval-Augmented Generation) pipeline. Upload your documents, embed them, and search with natural language — all stored in your browser.</p><p><strong>Sidebar item:</strong> Knowledge Base <strong>Route:</strong> <code>/rag</code></p><p><img src="'+t+'" alt="Knowledge Base interface"></p><h2 id="what-is-rag" tabindex="-1">What is RAG? <a class="header-anchor" href="#what-is-rag" aria-label="Permalink to &quot;What is RAG?&quot;">​</a></h2><p>RAG stands for <strong>Retrieval-Augmented Generation</strong>. Instead of relying only on what a model was trained on, RAG lets you feed it relevant excerpts from your own documents. The model then uses those excerpts as context to give more accurate, grounded answers.</p><h2 id="uploading-documents" tabindex="-1">Uploading Documents <a class="header-anchor" href="#uploading-documents" aria-label="Permalink to &quot;Uploading Documents&quot;">​</a></h2><p>Click <strong>Upload</strong> and select one or more files. Supported formats:</p><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>Parser</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td><td>pdfjs-dist (lazy-loaded)</td></tr><tr><td>Word</td><td><code>.docx</code></td><td>mammoth</td></tr><tr><td>Plain text</td><td><code>.txt</code>, <code>.md</code></td><td>Native</td></tr><tr><td>CSV</td><td><code>.csv</code></td><td>papaparse</td></tr></tbody></table><h2 id="the-ingestion-pipeline" tabindex="-1">The Ingestion Pipeline <a class="header-anchor" href="#the-ingestion-pipeline" aria-label="Permalink to &quot;The Ingestion Pipeline&quot;">​</a></h2><p>After upload, each document goes through three stages:</p><ol><li><strong>Parse</strong> — Extract raw text from the file format</li><li><strong>Chunk</strong> — Split the text into overlapping segments (configurable size and overlap)</li><li><strong>Embed</strong> — Generate a vector for each chunk using your chosen embedding model</li></ol><p>Progress is shown per document. Once complete, the document status changes to &quot;Ready&quot;.</p><h2 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to &quot;Searching&quot;">​</a></h2><ol><li>Type a natural-language query in the search bar.</li><li>Results appear ranked by <strong>cosine similarity</strong> — the most semantically relevant chunks first.</li><li>Each result shows: <ul><li>The matching text excerpt</li><li>The source document name</li><li>The similarity score</li><li>Metadata (page number, section, character offsets)</li></ul></li></ol><h2 id="managing-documents" tabindex="-1">Managing Documents <a class="header-anchor" href="#managing-documents" aria-label="Permalink to &quot;Managing Documents&quot;">​</a></h2><ul><li><strong>Enable/Disable</strong> — Toggle documents on or off for search. Disabled documents are not included in results.</li><li><strong>Delete</strong> — Remove a document and all its chunks from IndexedDB.</li><li><strong>Status indicators</strong> — Shows processing stage (parsing, chunking, embedding, ready, error).</li></ul><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>Everything is stored in <strong>IndexedDB</strong>, your browser&#39;s built-in database:</p><ul><li>Zero cost — no external services needed</li><li>Zero setup — works out of the box</li><li>Data stays on your machine</li><li>Survives browser refreshes (but not browser data clearing)</li></ul><h2 id="integration-with-chat" tabindex="-1">Integration with Chat <a class="header-anchor" href="#integration-with-chat" aria-label="Permalink to &quot;Integration with Chat&quot;">​</a></h2><p>When you have documents in the Knowledge Base, relevant chunks can be automatically included as context in your chat conversations, grounding the model&#39;s responses in your data.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Smaller chunks</strong> (200-400 tokens) tend to produce more precise search results.</li><li><strong>Embedding model matters</strong> — <code>nomic-embed-text</code> generally performs well for English text.</li><li>Large PDFs take time to process. The UI shows progress so you can track the pipeline.</li><li>You can upload multiple documents and search across all of them simultaneously.</li></ul>',24)])])}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
